#include "order_routes.h"

#include "http_request.h"
#include "http_response.h"
#include "session_store.h"
#include "sqlite3.h"
#include <inja.hpp>
#include <nlohmann/json.hpp>

#include <cstdlib>
#include <iostream>
#include <vector>

namespace {
bool can_checkout(const std::filesystem::path& root,std::string_view request){const auto username=session_username(request);if(username.empty())return false;sqlite3*db=nullptr;const auto file=(root/"data"/"system_control_center.db").string();if(sqlite3_open_v2(file.c_str(),&db,SQLITE_OPEN_READONLY,nullptr)!=SQLITE_OK)return false;sqlite3_stmt*s=nullptr;bool allowed=false;if(sqlite3_prepare_v2(db,"SELECT role FROM users WHERE username=?1",-1,&s,nullptr)==SQLITE_OK){sqlite3_bind_text(s,1,username.c_str(),-1,SQLITE_TRANSIENT);if(sqlite3_step(s)==SQLITE_ROW&&sqlite3_column_text(s,0)){const auto role=std::string(reinterpret_cast<const char*>(sqlite3_column_text(s,0)));allowed=role=="admin"||role=="operator";}}sqlite3_finalize(s);sqlite3_close(db);return allowed;}
std::string request_body(std::string_view request){const auto p=request.find("\r\n\r\n");return p==std::string_view::npos?std::string{}:std::string(request.substr(p+4));}
bool viewer_role(const std::filesystem::path& root,std::string_view request){const auto username=session_username(request);sqlite3*db=nullptr;const auto file=(root/"data"/"system_control_center.db").string();if(username.empty()||sqlite3_open_v2(file.c_str(),&db,SQLITE_OPEN_READONLY,nullptr)!=SQLITE_OK)return true;sqlite3_stmt*s=nullptr;bool viewer=true;if(sqlite3_prepare_v2(db,"SELECT role FROM users WHERE username=?1",-1,&s,nullptr)==SQLITE_OK){sqlite3_bind_text(s,1,username.c_str(),-1,SQLITE_TRANSIENT);if(sqlite3_step(s)==SQLITE_ROW&&sqlite3_column_text(s,0))viewer=std::string(reinterpret_cast<const char*>(sqlite3_column_text(s,0)))=="viewer";}sqlite3_finalize(s);sqlite3_close(db);return viewer;}
}

std::string checkout_route(const std::filesystem::path& root,std::string_view request){const auto username=session_username(request);if(username.empty())return redirect("/?error=Please%20sign%20in");sqlite3*db=nullptr;const auto file=(root/"data"/"system_control_center.db").string();if(sqlite3_open_v2(file.c_str(),&db,SQLITE_OPEN_READONLY,nullptr)!=SQLITE_OK)return response("500 Internal Server Error","text/plain; charset=utf-8","Database unavailable\n");nlohmann::json data;data["role"]="viewer";data["username"]=username;sqlite3_stmt*s=nullptr;if(sqlite3_prepare_v2(db,"SELECT role FROM users WHERE username=?1",-1,&s,nullptr)==SQLITE_OK){sqlite3_bind_text(s,1,username.c_str(),-1,SQLITE_TRANSIENT);if(sqlite3_step(s)==SQLITE_ROW)data["role"]=reinterpret_cast<const char*>(sqlite3_column_text(s,0));}sqlite3_finalize(s);data["read_only"]=data["role"]=="viewer";if(sqlite3_prepare_v2(db,"SELECT e.id,e.name,et.entity FROM entities e JOIN entity_type et ON e.entity_type=et.id ORDER BY e.name",-1,&s,nullptr)==SQLITE_OK)while(sqlite3_step(s)==SQLITE_ROW)data["customers"].push_back({{"id",sqlite3_column_int(s,0)},{"name",reinterpret_cast<const char*>(sqlite3_column_text(s,1))},{"entity_type",reinterpret_cast<const char*>(sqlite3_column_text(s,2))}});sqlite3_finalize(s);if(sqlite3_prepare_v2(db,"SELECT id,name,price,stock_quantity FROM products WHERE stock_quantity>0 ORDER BY name",-1,&s,nullptr)==SQLITE_OK)while(sqlite3_step(s)==SQLITE_ROW)data["products"].push_back({{"id",sqlite3_column_int(s,0)},{"name",reinterpret_cast<const char*>(sqlite3_column_text(s,1))},{"price",sqlite3_column_double(s,2)},{"stock_quantity",sqlite3_column_int(s,3)}});sqlite3_finalize(s);sqlite3_close(db);try{inja::Environment env((root/"templates").string());env.set_html_autoescape(true);return response("200 OK","text/html; charset=utf-8",env.render_file((root/"templates"/"checkout.html").string(),data));}catch(...){return response("500 Internal Server Error","text/plain; charset=utf-8","Checkout template unavailable\n");}}

std::string checkout_create_route(const std::filesystem::path& root,std::string_view request){if(!can_checkout(root,request))return redirect("/?error=Operator%20access%20required");const auto body=request_body(request);const int entity=static_cast<int>(std::strtol(form_value(body,"entity_id").c_str(),nullptr,10));const auto products=form_values(body,"product_id");const auto quantities=form_values(body,"quantity");if(entity<=0||products.empty()||products.size()!=quantities.size())return redirect("/checkout?error=Invalid%20order%20data");struct Line{int product_id;int quantity;};std::vector<Line>lines;for(size_t i=0;i<products.size();++i){const int id=static_cast<int>(std::strtol(products[i].c_str(),nullptr,10));const int qty=static_cast<int>(std::strtol(quantities[i].c_str(),nullptr,10));if(id<=0||qty<=0)return redirect("/checkout?error=Invalid%20order%20data");lines.push_back({id,qty});}sqlite3*db=nullptr;const auto file=(root/"data"/"system_control_center.db").string();if(sqlite3_open_v2(file.c_str(),&db,SQLITE_OPEN_READWRITE,nullptr)!=SQLITE_OK)return response("500 Internal Server Error","text/plain; charset=utf-8","Database unavailable\n");sqlite3_exec(db,"BEGIN",nullptr,nullptr,nullptr);sqlite3_stmt*s=nullptr;int result=SQLITE_OK;std::vector<double>prices;for(const auto&line:lines){result=sqlite3_prepare_v2(db,"SELECT price, stock_quantity FROM products WHERE id=?1",-1,&s,nullptr);double price=0;int stock=0;if(result==SQLITE_OK){sqlite3_bind_int(s,1,line.product_id);if(sqlite3_step(s)==SQLITE_ROW){price=sqlite3_column_double(s,0);stock=sqlite3_column_int(s,1);}else result=SQLITE_ERROR;}sqlite3_finalize(s);if(result!=SQLITE_OK||stock<line.quantity){result=SQLITE_ERROR;break;}prices.push_back(price);}sqlite3_int64 order_id=0;if(result==SQLITE_OK){result=sqlite3_prepare_v2(db,"INSERT INTO orders(entity_id,status) VALUES(?1,'COMPLETED')",-1,&s,nullptr);if(result==SQLITE_OK){sqlite3_bind_int(s,1,entity);result=sqlite3_step(s);}sqlite3_finalize(s);order_id=sqlite3_last_insert_rowid(db);}if(result==SQLITE_DONE)for(size_t i=0;i<lines.size();++i){result=sqlite3_prepare_v2(db,"INSERT INTO order_items(order_id,product_id,quantity,unit_price) VALUES(?1,?2,?3,?4)",-1,&s,nullptr);if(result==SQLITE_OK){sqlite3_bind_int64(s,1,order_id);sqlite3_bind_int(s,2,lines[i].product_id);sqlite3_bind_int(s,3,lines[i].quantity);sqlite3_bind_double(s,4,prices[i]);result=sqlite3_step(s);}sqlite3_finalize(s);if(result!=SQLITE_DONE)break;result=sqlite3_prepare_v2(db,"UPDATE products SET stock_quantity=stock_quantity-?1 WHERE id=?2 AND stock_quantity>=?1",-1,&s,nullptr);if(result==SQLITE_OK){sqlite3_bind_int(s,1,lines[i].quantity);sqlite3_bind_int(s,2,lines[i].product_id);result=sqlite3_step(s);if(result==SQLITE_DONE&&sqlite3_changes(db)!=1)result=SQLITE_ERROR;}sqlite3_finalize(s);if(result!=SQLITE_DONE)break;}sqlite3_exec(db,result==SQLITE_DONE?"COMMIT":"ROLLBACK",nullptr,nullptr,nullptr);sqlite3_close(db);return result==SQLITE_DONE?redirect("/orders/"+std::to_string(order_id)):redirect("/checkout?error=Insufficient%20stock%20or%20invalid%20order");}

std::string orders_route(const std::filesystem::path& root,std::string_view request){if(session_username(request).empty())return redirect("/?error=Please%20sign%20in");sqlite3*db=nullptr;const auto file=(root/"data"/"system_control_center.db").string();if(sqlite3_open_v2(file.c_str(),&db,SQLITE_OPEN_READONLY,nullptr)!=SQLITE_OK)return response("500 Internal Server Error","text/plain; charset=utf-8","Database unavailable\n");nlohmann::json data;sqlite3_stmt*s=nullptr;const char*orders="SELECT o.id,e.name,o.status,o.created_at,COALESCE(SUM(oi.quantity*oi.unit_price),0) FROM orders o JOIN entities e ON o.entity_id=e.id LEFT JOIN order_items oi ON oi.order_id=o.id GROUP BY o.id,e.name,o.status,o.created_at ORDER BY o.created_at DESC";if(sqlite3_prepare_v2(db,orders,-1,&s,nullptr)==SQLITE_OK)while(sqlite3_step(s)==SQLITE_ROW)data["orders"].push_back({{"order_id",sqlite3_column_int(s,0)},{"customer_name",reinterpret_cast<const char*>(sqlite3_column_text(s,1))},{"status",reinterpret_cast<const char*>(sqlite3_column_text(s,2))},{"created_at",reinterpret_cast<const char*>(sqlite3_column_text(s,3))},{"order_total",sqlite3_column_double(s,4)}});sqlite3_finalize(s);const char*items="SELECT oi.order_id,p.name,p.sku,oi.quantity,oi.unit_price,oi.quantity*oi.unit_price FROM order_items oi JOIN products p ON p.id=oi.product_id ORDER BY oi.order_id DESC,oi.id";if(sqlite3_prepare_v2(db,items,-1,&s,nullptr)==SQLITE_OK)while(sqlite3_step(s)==SQLITE_ROW)data["items"].push_back({{"order_id",sqlite3_column_int(s,0)},{"product_name",reinterpret_cast<const char*>(sqlite3_column_text(s,1))},{"sku",reinterpret_cast<const char*>(sqlite3_column_text(s,2))},{"quantity",sqlite3_column_int(s,3)},{"unit_price",sqlite3_column_double(s,4)},{"row_total",sqlite3_column_double(s,5)}});sqlite3_finalize(s);sqlite3_close(db);data["has_orders"]=data.contains("orders")&&!data["orders"].empty();try{inja::Environment env((root/"templates").string());env.set_html_autoescape(true);return response("200 OK","text/html; charset=utf-8",env.render_file((root/"templates"/"orders.html").string(),data));}catch(...){return response("500 Internal Server Error","text/plain; charset=utf-8","Orders template unavailable\n");}}

std::string order_detail_route(const std::filesystem::path& root,std::string_view request,int order_id){if(session_username(request).empty())return redirect("/?error=Please%20sign%20in");sqlite3*db=nullptr;const auto file=(root/"data"/"system_control_center.db").string();if(sqlite3_open_v2(file.c_str(),&db,SQLITE_OPEN_READONLY,nullptr)!=SQLITE_OK)return response("500 Internal Server Error","text/plain; charset=utf-8","Database unavailable\n");nlohmann::json data;data["back_url"]="/orders-view";data["back_label"]="Back to Orders";data["read_only"]=viewer_role(root,request);sqlite3_stmt*s=nullptr;const char*sql="SELECT o.id,e.name,o.status,o.created_at,COALESCE(SUM(oi.quantity*oi.unit_price),0) FROM orders o JOIN entities e ON o.entity_id=e.id LEFT JOIN order_items oi ON oi.order_id=o.id WHERE o.id=?1 GROUP BY o.id,e.name,o.status,o.created_at";if(sqlite3_prepare_v2(db,sql,-1,&s,nullptr)==SQLITE_OK){sqlite3_bind_int(s,1,order_id);if(sqlite3_step(s)==SQLITE_ROW)data["order"]={{"order_id",sqlite3_column_int(s,0)},{"customer_name",reinterpret_cast<const char*>(sqlite3_column_text(s,1))},{"status",reinterpret_cast<const char*>(sqlite3_column_text(s,2))},{"created_at",reinterpret_cast<const char*>(sqlite3_column_text(s,3))},{"order_total",sqlite3_column_double(s,4)}};}sqlite3_finalize(s);if(!data.contains("order")){sqlite3_close(db);return response("404 Not Found","text/plain; charset=utf-8","Order not found\n");}if(sqlite3_prepare_v2(db,"SELECT p.name,p.sku,oi.quantity,oi.unit_price,oi.quantity*oi.unit_price FROM order_items oi JOIN products p ON p.id=oi.product_id WHERE oi.order_id=?1 ORDER BY oi.id",-1,&s,nullptr)==SQLITE_OK){sqlite3_bind_int(s,1,order_id);while(sqlite3_step(s)==SQLITE_ROW)data["items"].push_back({{"product_name",reinterpret_cast<const char*>(sqlite3_column_text(s,0))},{"sku",reinterpret_cast<const char*>(sqlite3_column_text(s,1))},{"quantity",sqlite3_column_int(s,2)},{"unit_price",sqlite3_column_double(s,3)},{"row_total",sqlite3_column_double(s,4)}});}sqlite3_finalize(s);sqlite3_close(db);try{inja::Environment env((root/"templates").string());env.set_html_autoescape(true);return response("200 OK","text/html; charset=utf-8",env.render_file((root/"templates"/"order_detail.html").string(),data));}catch(...){return response("500 Internal Server Error","text/plain; charset=utf-8","Order template unavailable\n");}}

std::string refund_route(const std::filesystem::path& root,std::string_view request,int order_id){if(!can_checkout(root,request))return redirect("/?error=Operator%20access%20required");const auto body=request_body(request);const auto reason=form_value(body,"reason");const auto username=session_username(request);sqlite3*db=nullptr;const auto file=(root/"data"/"system_control_center.db").string();if(sqlite3_open_v2(file.c_str(),&db,SQLITE_OPEN_READWRITE,nullptr)!=SQLITE_OK)return response("500 Internal Server Error","text/plain; charset=utf-8","Database unavailable\n");sqlite3_exec(db,"BEGIN",nullptr,nullptr,nullptr);sqlite3_stmt*s=nullptr;int result=sqlite3_prepare_v2(db,"SELECT status,COALESCE(SUM(oi.quantity*oi.unit_price),0) FROM orders o LEFT JOIN order_items oi ON oi.order_id=o.id WHERE o.id=?1 GROUP BY o.id,o.status",-1,&s,nullptr);std::string status;double amount=0;if(result==SQLITE_OK){sqlite3_bind_int(s,1,order_id);if(sqlite3_step(s)==SQLITE_ROW){status=reinterpret_cast<const char*>(sqlite3_column_text(s,0));amount=sqlite3_column_double(s,1);}else result=SQLITE_ERROR;}sqlite3_finalize(s);sqlite3_int64 refund_id=0;if(result==SQLITE_OK&&status=="COMPLETED"){result=sqlite3_prepare_v2(db,"INSERT INTO order_refunds(order_id,refunded_by,reason,amount) SELECT ?1,id,?2,?3 FROM users WHERE username=?4",-1,&s,nullptr);if(result==SQLITE_OK){const auto refund_reason=reason.empty()?std::string("Customer refund"):reason;sqlite3_bind_int(s,1,order_id);sqlite3_bind_text(s,2,refund_reason.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_double(s,3,amount);sqlite3_bind_text(s,4,username.c_str(),-1,SQLITE_TRANSIENT);result=sqlite3_step(s);}sqlite3_finalize(s);refund_id=sqlite3_last_insert_rowid(db);}if(result==SQLITE_DONE){result=sqlite3_prepare_v2(db,"SELECT id,product_id,quantity,unit_price FROM order_items WHERE order_id=?1",-1,&s,nullptr);if(result==SQLITE_OK){sqlite3_bind_int(s,1,order_id);while(sqlite3_step(s)==SQLITE_ROW){sqlite3_stmt*x=nullptr;const int item=sqlite3_column_int(s,0),product=sqlite3_column_int(s,1),quantity=sqlite3_column_int(s,2);const double price=sqlite3_column_double(s,3);if(sqlite3_prepare_v2(db,"INSERT INTO order_refund_items(refund_id,order_item_id,quantity,unit_price) VALUES(?1,?2,?3,?4)",-1,&x,nullptr)!=SQLITE_OK){result=SQLITE_ERROR;break;}sqlite3_bind_int64(x,1,refund_id);sqlite3_bind_int(x,2,item);sqlite3_bind_int(x,3,quantity);sqlite3_bind_double(x,4,price);if(sqlite3_step(x)!=SQLITE_DONE)result=SQLITE_ERROR;sqlite3_finalize(x);if(result!=SQLITE_DONE)break;if(sqlite3_prepare_v2(db,"UPDATE products SET stock_quantity=stock_quantity+?1 WHERE id=?2",-1,&x,nullptr)!=SQLITE_OK){result=SQLITE_ERROR;break;}sqlite3_bind_int(x,1,quantity);sqlite3_bind_int(x,2,product);if(sqlite3_step(x)!=SQLITE_DONE||sqlite3_changes(db)!=1)result=SQLITE_ERROR;sqlite3_finalize(x);if(result!=SQLITE_DONE)break;}}sqlite3_finalize(s);}if(result==SQLITE_DONE){result=sqlite3_prepare_v2(db,"UPDATE orders SET status='REFUNDED' WHERE id=?1",-1,&s,nullptr);if(result==SQLITE_OK){sqlite3_bind_int(s,1,order_id);result=sqlite3_step(s);}sqlite3_finalize(s);}sqlite3_exec(db,result==SQLITE_DONE?"COMMIT":"ROLLBACK",nullptr,nullptr,nullptr);sqlite3_close(db);return redirect("/orders/"+std::to_string(order_id));}
